return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Een multifunctionele plugin om meertalige content te exporteren en importeren.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'De import-trigger accepteert de sleutel niet langer in de URL. Verzend deze in een POST-body.','Method Not Allowed'=>'Methode niet toegestaan','Unauthorized'=>'Niet geautoriseerd','No items to process'=>'Geen items om te verwerken','No Content'=>'Geen inhoud','Import process completed'=>'Importproces voltooid','Success'=>'Succes','Import process failed'=>'Importproces mislukt','Internal Server Error'=>'Interne serverfout','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d item kon niet worden verwerkt en is overgeslagen.' . "\0" . '%1$s: %2$d items konden niet worden verwerkt en zijn overgeslagen.','Cleaning Up Post Data'=>'Berichtgegevens opschonen','Removing temporary and import-related post meta data.'=>'Tijdelijke en importgerelateerde metadata van berichten verwijderen.','Cleaning Up Term Data'=>'Termgegevens opschonen','Removing temporary and import-related term meta data.'=>'Tijdelijke en importgerelateerde metadata van termen verwijderen.','Connecting Post Image Attachments'=>'Bijlagen van berichtafbeeldingen koppelen','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'ID\'s van thumbnail- en galerijbijlagen op vertaalde berichten, producten en CPT\'s bijwerken om naar hun vertaalde equivalenten te verwijzen.','Connecting Inline Term Translations'=>'Vertalingen van inline-termen koppelen','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Berichten met een enkele taxonomieterm scannen om de aan deze berichten toegewezen termen te identificeren en te koppelen aan hun vertalingen.','Deleting Obsolete Original Terms'=>'Verouderde oorspronkelijke termen verwijderen','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Oorspronkelijke termen verwijderen die niet langer nodig zijn na het maken van duplicaten voor termen met dezelfde naam. Ervoor zorgen dat er geen berichten aan deze oorspronkelijke termen zijn gekoppeld.','Duplicating Terms with Shared Names Across Languages'=>'Termen met gedeelde namen over talen dupliceren','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Duplicaten maken in de juiste taal voor termen die dezelfde naam delen over talen heen, maar bij berichten in verschillende talen horen.','Fixing Imported Post Slugs'=>'Slugs van geïmporteerde berichten herstellen','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Slugs van vertaalde berichten opnieuw genereren om conflicten met de originelen te voorkomen.','Clearing Translations Cache'=>'Cache van vertalingen wissen','Invalidating the persistent cache so it can be regenerated.'=>'De persistente cache ongeldig maken zodat deze opnieuw kan worden gegenereerd.','Marking Parent Terms for Connection'=>'Bovenliggende termen markeren voor koppeling','Collecting parent terms to connect their translations in the next step.'=>'Bovenliggende termen verzamelen om hun vertalingen in de volgende stap te koppelen.','Connecting Posts with Correct Term Translations'=>'Berichten koppelen aan de juiste termvertalingen','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Ervoor zorgen dat berichten zijn gekoppeld aan termen in de juiste taal, vooral als u dezelfde termnamen in verschillende talen heeft.','Sending Posts for Automatic Translation'=>'Berichten verzenden voor automatische vertaling','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Automatische vertaaltaken maken voor berichten die in de geëxporteerde gegevens zijn gemarkeerd voor automatische vertaling.','Setting Attachments\' Language'=>'Taal van bijlagen instellen','Assigning a language to imported attachments.'=>'Een taal toewijzen aan geïmporteerde bijlagen.','Updating Final Post Status'=>'Uiteindelijke berichtstatus bijwerken','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'De berichtstatus instellen op basis van het veld “_wpml_import_after_process_post_status” uit het importbestand (indien opgegeven).','Identifying Inline Term Languages'=>'Talen van inline-termen identificeren','Identifying and setting the language of terms created during post imports.'=>'De taal identificeren en instellen van termen die zijn gemaakt tijdens het importeren van berichten.','Setting Posts’ Language'=>'Taal van berichten instellen','Connecting posts to the default language and translations.'=>'Berichten koppelen aan de standaardtaal en vertalingen.','Setting Terms’ Language'=>'Taal van termen instellen','Connecting taxonomy terms to the default (original) language and translations.'=>'Taxonomietermen koppelen aan de standaardtaal (oorspronkelijke taal) en vertalingen.','Setting Parent Terms\' Language'=>'Taal van bovenliggende termen instellen','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Taal toewijzen aan bovenliggende taxonomietermen die er geen hebben, op basis van de taal die is toegewezen aan hun onderliggende items.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Migreert u uw meertalige site? Vergeet niet om ook %s op uw nieuwe site te installeren voordat u uw content importeert, zodat we alle vertalingen kunnen herstellen.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Migreert u uw meertalige winkel? Met %1$s en %2$s kunt u uw vertaalde content overzetten naar een nieuwe site, inclusief cross-sells, upsells en productkenmerken.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Migreert u uw meertalige winkel? Vergeet niet om %1$s en %2$s op uw nieuwe site te installeren voordat u uw content importeert, zodat we alle vertalingen kunnen herstellen.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Wilt u uw meertalige content importeren? Vergeet niet om %s op uw oorspronkelijke site te installeren voordat u de content exporteert, zodat we alle vertalingen hier kunnen importeren.','Looking to import your multilingual content? Install %1$s on this site.'=>'Wilt u uw meertalige content importeren? Installeer %1$s op deze site.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Vergeet niet om ook %2$s en %3$s in uw oorspronkelijke winkel in te schakelen voordat u de content exporteert, zodat we alle vertalingen hier kunnen importeren.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Wilt u uw meertalige content importeren? Vergeet niet om %1$s and %2$s in uw oorspronkelijke winkel in te schakelen voordat u de content exporteert, zodat we alle vertalingen hier kunnen importeren.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Overschakelen naar alle talen','Linking Product Attribute Translations'=>'Vertalingen van productkenmerken koppelen','Connecting product attributes to their translations based on associated product variations.'=>'Productkenmerken koppelen aan hun vertalingen op basis van bijbehorende productvariaties.','Updating Related Products On Translations'=>'Gerelateerde producten op vertalingen bijwerken','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Verwijzingen naar upsells, cross-sells en gegroepeerde producten instellen in de juiste taal.','Importing Custom Attribute Labels'=>'Labels van aangepaste kenmerken importeren','Importing labels for product-specific (custom) attributes from the exported data.'=>'Labels voor productspecifieke (aangepaste) kenmerken importeren uit de geëxporteerde gegevens.','You are about to export all your products in all languages at once.'=>'U staat op het punt om al uw producten in alle talen tegelijk te exporteren.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Vergeet niet om %1$s en %2$s op uw nieuwe site te installeren voordat u uw content importeert, zodat we alle vertalingen kunnen herstellen.','You are about to export your products in %s.'=>'U staat op het punt om uw producten te exporteren in het %s.','Registering Product Attributes'=>'Productkenmerken registreren','Identifying and registering attributes created during product imports for translation.'=>'Kenmerken die zijn gemaakt tijdens productimports identificeren en registreren voor vertaling.','Identifying Product Attribute Languages'=>'Talen van productkenmerken identificeren','Identifying and setting the language of attributes created during product imports.'=>'De taal identificeren en instellen van kenmerken die zijn gemaakt tijdens productimports.','Export and Import'=>'Exporteren en importeren','I’m using the built-in %s export/import tool'=>'Ik gebruik de ingebouwde %s export/import-tool','I’m using %s plugin'=>'Ik gebruik de %s-plugin','(%1$d/%2$d items)'=>'(%1$d/%2$d items)','%d skipped'=>'%d overgeslagen','(no items)'=>'(geen items)','Counting items...'=>'Items tellen...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Vertel ons eerst hoe u de content gaat maken die u gaat importeren:','Continue'=>'Doorgaan','I’m using %1$s and %2$s plugins'=>'Ik gebruik de plugins %1$s en %2$s','I’m using a different method to export from this site'=>'Ik gebruik een andere methode om van deze site te exporteren','I’m exporting the content from this site'=>'Ik exporteer de content van deze site','I’m exporting the content from a different website or system'=>'Ik exporteer de content van een andere website of een ander systeem','Before importing, add language columns to your content'=>'Voeg taalkolommen toe aan uw content voordat u gaat importeren','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Zorg ervoor dat uw importbestand de volgende kolommen (aangepaste velden) met taalgegevens bevat:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Een waarde die hetzelfde is voor alle vertalingen van elk item. Op e-commerce sites is dit vaak de SKU.','%s: The language code for each item.'=>'%s: De taalcode voor elk item.','And, you can include these two columns if needed:'=>'En u kunt indien nodig deze twee kolommen toevoegen:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Als dit item een vertaling is, stel deze kolom dan in op de code van de brontaal. Als het geen vertaling is, laat deze dan leeg.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Instellen op “draft” (concept) of “published” (gepubliceerd) om de publicatiestatus van het bericht te bepalen na het aanpassen van de talen. Meestal is deze waarde “published”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Hier is een voorbeeld van het importeren van twee items in de talen van uw site ((%s)):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Zodra u taalkolommen heeft toegevoegd aan uw meertalige contentbestand, importeert u het naar uw site met de import-plugin van uw voorkeur.','Before importing, your content needs language information'=>'Uw content heeft taalgegevens nodig voordat u gaat importeren','%s will add the necessary language information to your export.'=>'%s voegt de nodige taalgegevens toe aan uw export.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importeer uw meertalige contentbestand naar de site met de import-plugin van uw voorkeur.','Use your favorite import plugin'=>'Gebruik uw favoriete import-plugin','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Nadat u de content heeft geïmporteerd, worden de juiste taalgegevens nog steeds niet weergegeven. Daarom raden we aan om nieuwe content als concepten te importeren. Als u updates importeert, kunt u reeds gepubliceerde content als gepubliceerd behouden.','Return here, to %s, to set languages and connect translations'=>'Keer hier terug naar %s om talen in te stellen en vertalingen te koppelen','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Wanneer u deze pagina bezoekt nadat u content met taalgegevens heeft geïmporteerd, kunt u %s uitvoeren om talen toe te passen en vertalingen te koppelen.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Al geïmporteerd en ziet u dit scherm nog steeds? %1$sProbleemoplossing %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Hoe u content in meerdere talen kunt exporteren en importeren','%s is ready to update your imported content'=>'%s is klaar om uw geïmporteerde content bij te werken','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Goed gedaan. We zien %1$d termen en %2$d berichten die zijn geïmporteerd en taalgegevens nodig hebben.','Good job. We see %d terms that are imported and need language information.'=>'Goed gedaan. We zien %d termen die zijn geïmporteerd en taalgegevens nodig hebben.','Good job. We see %d posts that are imported and need language information.'=>'Goed gedaan. We zien %d berichten die zijn geïmporteerd en taalgegevens nodig hebben.','Run WPML Import'=>'WPML Import uitvoeren','Multilingual Import Complete'=>'Meertalige import voltooid']];